    /**
     * Field metadata (error, touched, dirty state).
     */
    meta: {
        error: string | undefined;
        touched: boolean;
        isDirty: boolean;
    };
    /**
     * Normalized field configuration.
     */
    config: EntityField;
    /**
     * Whether field is editable (based on role, operation, config).
